const synonymToCanonical = new Map<string, string>();
for (const [canonical, synonyms] of Object.entries(SKILL_SYNONYMS)) {
  synonymToCanonical.set(canonical, canonical);
  for (const syn of synonyms) synonymToCanonical.set(syn, canonical);
}

function normalizeSkill(skill: string): string {
  // Preserve meaningful symbols: C#, C++, .NET, etc.
  const lower = skill.toLowerCase().trim()
    .replace(/\s+/g, ' ')
    .replace(/[\/\-]/g, ''); // Only strip slashes and hyphens, NOT dots, #, or +
  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
}

function tokenize(term: string): string[] {
  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
}

function tokenOverlap(a: string, b: string): number {
  const tokensA = tokenize(a);
  const tokensB = tokenize(b);
  if (tokensA.length === 0 || tokensB.length === 0) return 0;
  const setB = new Set(tokensB);
  const matched = tokensA.filter(t => setB.has(t)).length;
  return matched / Math.max(tokensA.length, tokensB.length);
}

function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
  const normalizedJd = normalizeSkill(jdTerm);
  for (const rt of resumeTerms) {
    const normalizedResume = normalizeSkill(rt);
    if (normalizedJd === normalizedResume) return true;
    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
  }
  return false;
}

function extractResumeTerms(parsedJson: any): string[] {
  const p = parsedJson || {};
  const resumeSkills = (p.skills_with_evidence || []).map((s: any) =>
    (typeof s === 'string' ? s : s.skill || s.name || '').toLowerCase()
  );
  const resumeTools = (p.tools || []).map((t: string) => t.toLowerCase());
  const domains = p.domain_experience ? [p.domain_experience.toLowerCase()] : [];
  const roleTitles = (p.roles_with_dates || []).map((r: any) => (r.title || r.role || '').toLowerCase());
  return [...resumeSkills, ...resumeTools, ...domains, ...roleTitles].filter(Boolean);
}

