interface ExperienceBand {
  min_years: number;
  max_years: number;
  score: number;
  label: string;
}

interface EducationLevel {
  level: string;
  score: number;
  aliases: string[];
}

function mergeSkillSynonyms(adminSynonyms: Record<string, string[]>) {
  const merged = { ...SKILL_SYNONYMS };
  for (const [canonical, syns] of Object.entries(adminSynonyms)) {
    const key = canonical.toLowerCase().trim();
    merged[key] = [...new Set([...(merged[key] || []), ...syns.map(s => s.toLowerCase().trim())])];
  }
  // Rebuild the lookup map
  for (const [canonical, syns] of Object.entries(merged)) {
    synonymToCanonical.set(canonical, canonical);
    for (const syn of syns) synonymToCanonical.set(syn, canonical);
  }
  return merged;
}

