serve(async (req) => {
  const cors = corsHeaders(req);

  const preflight = handlePreflight(req);
  if (preflight) return preflight;

  try {
    const body = await req.json();
    const { job_id, resume_ids, _internal, _all_target_ids } = body;
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!job_id || !UUID_RE.test(job_id)) throw new Error("Missing or invalid job_id");

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    let userId: string;

    if (_internal) {
      userId = body._user_id;
      if (!userId) throw new Error("Internal call missing _user_id");
      console.log(`Continuation call for job ${job_id}: processing ${resume_ids?.length || 0} resumes`);
    } else {
      const authHeader = req.headers.get("Authorization");
      if (!authHeader) {
        return new Response(JSON.stringify({ error: "No auth header — please sign in and try again." }), {
          status: 401, headers: { ...cors, "Content-Type": "application/json" },
        });
      }
      const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
      const supabaseUser = createClient(SUPABASE_URL, anonKey, {
        global: { headers: { Authorization: authHeader } },
      });
      const { data: { user: authUser }, error: authErr } = await supabaseUser.auth.getUser();
      if (authErr || !authUser) {
        console.error("Auth failed:", authErr?.message || "No user returned");
        return new Response(JSON.stringify({ error: "Unauthorized — session may have expired. Please refresh and try again." }), {
          status: 401, headers: { ...cors, "Content-Type": "application/json" },
        });
      }
      userId = authUser.id;

      const oneMinAgo = new Date(Date.now() - 60000).toISOString();
      const { count } = await supabase
        .from("jobs").select("id", { count: "exact", head: true })
        .eq("user_id", userId).gte("created_at", oneMinAgo);
      if ((count ?? 0) > 3) {
        return new Response(JSON.stringify({ error: "Rate limit: max 3 jobs per minute" }), {
          status: 429, headers: { ...cors, "Content-Type": "application/json" },
        });
      }
    }

    const { data: job } = await supabase.from("jobs").select("*").eq("id", job_id).single();
    if (!job) throw new Error("Job not found");
    if (!_internal && job.user_id !== userId) throw new Error("Unauthorized");

    const jdAnalysis = job.jd_analysis_json;
    const dynamicWeights = job.dynamic_weights_json;
    const jdEmbedding = job.jd_embedding;

    if (!jdAnalysis || !dynamicWeights) {
      return new Response(
        JSON.stringify({ error: "JD analysis required. Please analyze the job description first." }),
        { status: 400, headers: { ...cors, "Content-Type": "application/json" } }
      );
    }

    let targetResumeIds: string[] = (resume_ids || []).filter((id: string) => UUID_RE.test(id));
    if (!targetResumeIds.length && !_internal) {
      const { data: allResumes } = await supabase.from("resumes").select("id").eq("job_id", job_id);
      targetResumeIds = (allResumes || []).map((r: any) => r.id);
    }

    if (targetResumeIds.length === 0) {
      return new Response(JSON.stringify({ error: "No resumes to rank" }), {
        status: 400, headers: { ...cors, "Content-Type": "application/json" },
      });
    }

    const allTargetIds: string[] = _all_target_ids || targetResumeIds;

    // Fetch platform config for max resumes limit
    const { data: platformConfig } = await supabase.from("platform_config").select("max_resumes_per_job").limit(1).single();
    const maxResumesPerJob = platformConfig?.max_resumes_per_job ?? 1000;

    if (!_internal) {
      const creditsToCharge = Math.min(targetResumeIds.length, maxResumesPerJob);
      const { data: creditOk } = await supabase.rpc("deduct_credits", {
        _user_id: userId, _job_id: job_id, _amount: creditsToCharge,
      });
      if (!creditOk) {
        await supabase.from("jobs").update({ status: "failed" }).eq("id", job_id);
        return new Response(JSON.stringify({ error: "Insufficient credits" }), {
          status: 402, headers: { ...cors, "Content-Type": "application/json" },
        });
      }

      await supabase.from("jobs").update({
        status: "processing", processing_started_at: new Date().toISOString(),
      }).eq("id", job_id);

      try {
        await supabase.functions.invoke("rank-resumes", {
          body: { job_id, resume_ids: targetResumeIds, _internal: true, _user_id: userId, _all_target_ids: allTargetIds },
        });
      } catch (invokeErr) {
        console.error("Initial self-invocation failed:", invokeErr);
        await logSystemError({ function_name: "rank-resumes", error_type: "INITIAL_SELF_INVOKE_FAILED", severity: "critical", error_message: errorToMessage(invokeErr), error_stack: errorToStack(invokeErr), job_id, user_id: userId });
        await supabase.from("jobs").update({ status: "failed" }).eq("id", job_id);
        throw invokeErr;
