"use client";

import { useState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useSeoSettings } from "@/hooks/useSeoSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { toast } from "sonner";
import { Save, Loader2, Code, Eye } from "lucide-react";
import { logAuditAction } from "@/lib/auditLog";

const StructuredDataTab = () => {
  const qc = useQueryClient();
  const { settings, isLoading } = useSeoSettings();
  const [saving, setSaving] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [showPreview, setShowPreview] = useState(false);

  const [form, setForm] = useState({
    structured_data_enabled: true,
    organization_name: "",
    organization_url: "",
    organization_logo_url: "",
    organization_description: "",
  });

  if (settings && !loaded) {
    const s = settings as Record<string, unknown>;
    setForm({
      structured_data_enabled: (s.structured_data_enabled as boolean) ?? true,
      organization_name: (s.organization_name as string) ?? "",
      organization_url: (s.organization_url as string) ?? "",
      organization_logo_url: (s.organization_logo_url as string) ?? "",
      organization_description: (s.organization_description as string) ?? "",
    });
    setLoaded(true);
  }

  const save = async () => {
    setSaving(true);
    try {
      const { error } = await supabase.from("seo_settings")
        .update(form)
        .eq("id", settings?.id);
      if (error) { toast.error(error.message); return; }
      toast.success("Structured data settings saved");
      logAuditAction("seo.update", "seo_settings", settings?.id, { section: "structured_data", ...form });
      qc.invalidateQueries({ queryKey: ["seo_settings"] });
    } finally {
      setSaving(false);
    }
  };

  const generateJsonLd = () => {
    const org: Record<string, unknown> = {
      "@context": "https://schema.org",
      "@type": "Organization",
      name: form.organization_name || "Rankora",
      description: form.organization_description || settings?.site_description || "",
    };
    if (form.organization_url) org.url = form.organization_url;
    if (form.organization_logo_url) org.logo = form.organization_logo_url;

    const webapp: Record<string, unknown> = {
      "@context": "https://schema.org",
      "@type": "WebApplication",
      name: settings?.site_title || "Rankora",
      description: settings?.site_description || "",
      applicationCategory: "BusinessApplication",
      operatingSystem: "Web",
      offers: {
        "@type": "Offer",
        price: "0",
        priceCurrency: "USD",
      },
    };
    if (form.organization_url) webapp.url = form.organization_url;

    return JSON.stringify([org, webapp], null, 2);
  };

  if (isLoading) return <div className="flex items-center gap-2 text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2"><Code className="h-5 w-5" /> Structured Data (JSON-LD)</CardTitle>
          <CardDescription>Schema.org structured data helps search engines understand your site. This generates Organization and WebApplication schemas automatically.</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-3">
            <Switch checked={form.structured_data_enabled} onCheckedChange={(v) => setForm({ ...form, structured_data_enabled: v })} />
            <Label>Enable Structured Data</Label>
          </div>

          {form.structured_data_enabled && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <Label>Organization Name</Label>
                <Input value={form.organization_name} onChange={(e) => setForm({ ...form, organization_name: e.target.value })} placeholder="Rankora" />
              </div>
              <div>
                <Label>Organization URL</Label>
                <Input value={form.organization_url} onChange={(e) => setForm({ ...form, organization_url: e.target.value })} placeholder="https://yourdomain.com" />
              </div>
              <div>
                <Label>Logo URL</Label>
                <Input value={form.organization_logo_url} onChange={(e) => setForm({ ...form, organization_logo_url: e.target.value })} placeholder="https://yourdomain.com/logo.png" />
              </div>
              <div className="sm:col-span-2">
                <Label>Organization Description</Label>
                <Textarea value={form.organization_description} onChange={(e) => setForm({ ...form, organization_description: e.target.value })} placeholder="Brief description of your organization..." className="min-h-[80px]" />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {form.structured_data_enabled && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Generated JSON-LD Preview</CardTitle>
              <Button variant="outline" size="sm" onClick={() => setShowPreview(!showPreview)}>
                <Eye className="h-3 w-3 mr-1" /> {showPreview ? "Hide" : "Show"} Preview
              </Button>
            </div>
          </CardHeader>
          {showPreview && (
            <CardContent>
              <pre className="text-xs font-mono bg-muted p-3 rounded-md overflow-auto max-h-80 whitespace-pre-wrap">
                {generateJsonLd()}
              </pre>
            </CardContent>
          )}
        </Card>
      )}

      <Button onClick={save} disabled={saving}>
        {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
        Save Structured Data
      </Button>
    </div>
  );

