// Uses the free qr.io API or falls back to a Google Charts-compatible URL.
function QrCodeImage({ url }: { url: string }) {
  const qrSrc = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(url)}&size=160x160&format=png&margin=4`;
  return (
    <img
      src={qrSrc}
      alt="QR Code"
      width={160}
      height={160}
      className="rounded-lg border border-border"
      loading="lazy"
    />
  );
}

